{
  "schema_version": "sections_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "sections": [
        {
          "section_id": 1,
          "title": "The Routine Grind",
          "intent": "Establish the baseline reality of the tutorial dungeon before the collapse.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Kaelen witnesses the first UI glitch during a standard mob pull."
        },
        {
          "section_id": 2,
          "title": "The Void Breach",
          "intent": "Escalate the glitch into a full-scale environmental collapse.",
          "section_role": "conflict",
          "target_scene_count": 3,
          "end_condition": "The dungeon boss is consumed by purple static and transformed into a Void-horror."
        },
        {
          "section_id": 3,
          "title": "The Great Escape",
          "intent": "Force a desperate flight from the crumbling instance.",
          "section_role": "climax",
          "target_scene_count": 2,
          "end_condition": "Kaelen exits the dungeon portal just as the instance is flagged as 'Corrupted'."
        }
      ]
    },
    {
      "chapter_id": 2,
      "sections": [
        {
          "section_id": 1,
          "title": "The Quiet After the Storm",
          "intent": "Allow Kaelen to assess his survival and the state of his character.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Kaelen finds a secluded spot to open his broken character sheet."
        },
        {
          "section_id": 2,
          "title": "Decoding the Glitch",
          "intent": "Introduce the mechanics of the Void-Touched class through experimentation.",
          "section_role": "investigation",
          "target_scene_count": 4,
          "end_condition": "Kaelen successfully triggers his first 'Void-Touched' passive skill."
        },
        {
          "section_id": 3,
          "title": "The First Exploit",
          "intent": "Demonstrate the power of the new class by breaking a minor game rule.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Kaelen uses a glitch-jump to bypass a high-level locked gate."
        }
      ]
    },
    {
      "chapter_id": 3,
      "sections": [
        {
          "section_id": 1,
          "title": "The Deletion Protocol",
          "intent": "Establish the ticking clock as the System attempts to purge the zone.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "A system-wide broadcast announces the immediate deletion of the starter zone."
        },
        {
          "section_id": 2,
          "title": "Through the Pixelated Woods",
          "intent": "Navigate a landscape that is literally dissolving into code.",
          "section_role": "conflict",
          "target_scene_count": 3,
          "end_condition": "Kaelen reaches the shimmering instance barrier at the edge of the world."
        },
        {
          "section_id": 3,
          "title": "Breaking the Barrier",
          "intent": "Use Void powers to force an exit into the persistent world.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Kaelen steps through the pixelated barrier into the open world of Oakhaven."
        }
      ]
    },
    {
      "chapter_id": 4,
      "sections": [
        {
          "section_id": 1,
          "title": "The Road to Oakhaven",
          "intent": "Show the scale of the Void-breach outside the tutorial zone.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Kaelen arrives at the city gates to find them under siege by 'null' entities."
        },
        {
          "section_id": 2,
          "title": "City of Chaos",
          "intent": "Explore the social and physical breakdown within the hub city.",
          "section_role": "investigation",
          "target_scene_count": 4,
          "end_condition": "Kaelen secures a room in a tavern that is temporarily shielded from glitches."
        },
        {
          "section_id": 3,
          "title": "The Hunted",
          "intent": "Introduce the System's automated enforcers as a primary antagonist.",
          "section_role": "conflict",
          "target_scene_count": 4,
          "end_condition": "Kaelen witnesses a 'glitched' player being dragged away by System Enforcers."
        }
      ]
    },
    {
      "chapter_id": 5,
      "sections": [
        {
          "section_id": 1,
          "title": "Underworld Contacts",
          "intent": "Navigate the city's criminal element to find a solution to Kaelen's instability.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Kaelen meets a rogue coder in the city's sewers who knows about stabilizers."
        },
        {
          "section_id": 2,
          "title": "The Stabilizer Heist",
          "intent": "Infiltrate a high-security vault to steal a prototype item.",
          "section_role": "conflict",
          "target_scene_count": 4,
          "end_condition": "Kaelen retrieves the prototype stabilizer from the vault."
        },
        {
          "section_id": 3,
          "title": "Integration",
          "intent": "Stabilize Kaelen's power and prepare for the next phase of growth.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Kaelen installs the stabilizer, successfully stopping his mana-implosion."
        }
      ]
    },
    {
      "chapter_id": 6,
      "sections": [
        {
          "section_id": 1,
          "title": "The Crypt Entrance",
          "intent": "Begin the first major dungeon crawl to retrieve a Void Shard.",
          "section_role": "setup",
          "target_scene_count": 4,
          "end_condition": "Kaelen defeats the corrupted gatekeeper of the Sunken Crypt."
        },
        {
          "section_id": 2,
          "title": "Navigating the Glitch-Maze",
          "intent": "Challenge Kaelen with environmental puzzles and evolved monsters.",
          "section_role": "conflict",
          "target_scene_count": 4,
          "end_condition": "Kaelen reaches the central chamber of the crypt."
        },
        {
          "section_id": 3,
          "title": "The Shard Guardian",
          "intent": "A high-intensity boss fight for the first major power-up.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "The Void Shard is absorbed into Kaelen's chest, triggering a global announcement."
        }
      ]
    },
    {
      "chapter_id": 7,
      "sections": [
        {
          "section_id": 1,
          "title": "Data Extraction",
          "intent": "Use the Shard to access hidden information about the world.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The first developer log begins to play within Kaelen's UI."
        },
        {
          "section_id": 2,
          "title": "The Truth Revealed",
          "intent": "Deliver the core mystery revelation about the Void's origin.",
          "section_role": "investigation",
          "target_scene_count": 3,
          "end_condition": "Kaelen discovers the System was designed to fail by its own Architects."
        },
        {
          "section_id": 3,
          "title": "The Rebel's Path",
          "intent": "Shift Kaelen's motivation from survival to active rebellion.",
          "section_role": "climax",
          "target_scene_count": 2,
          "end_condition": "Kaelen decides to find an ally who knows the old world's code."
        }
      ]
    },
    {
      "chapter_id": 8,
      "sections": [
        {
          "section_id": 1,
          "title": "Finding the Sentinel",
          "intent": "Track down a potential ally in the wilderness.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Kaelen tracks Lyra to a hidden camp in the mountains."
        },
        {
          "section_id": 2,
          "title": "The Purge Squad Attack",
          "intent": "Force Kaelen and Lyra to work together against a common enemy.",
          "section_role": "conflict",
          "target_scene_count": 4,
          "end_condition": "Kaelen and Lyra defeat the System 'Purge' squad together."
        },
        {
          "section_id": 3,
          "title": "The Pact",
          "intent": "Solidify the alliance and set the next objective.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Lyra shakes Kaelen's hand, agreeing to lead him to the Rift Core."
        }
      ]
    },
    {
      "chapter_id": 9,
      "sections": [
        {
          "section_id": 1,
          "title": "The Storm Approaches",
          "intent": "Build tension as the first true Void-storm hits the city.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The first purple lightning strike hits the city walls of Oakhaven."
        },
        {
          "section_id": 2,
          "title": "Holding the Line",
          "intent": "A massive battle to protect the city from being overwritten.",
          "section_role": "conflict",
          "target_scene_count": 4,
          "end_condition": "Kaelen uses a massive Void-AoE to clear the main gate of 'null' entities."
        },
        {
          "section_id": 3,
          "title": "The Aftermath",
          "intent": "Show the cost of the defense and the System's escalation.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "The surge recedes, leaving Kaelen marked for immediate 'Hard Deletion'."
        }
      ]
    },
    {
      "chapter_id": 10,
      "sections": [
        {
          "section_id": 1,
          "title": "The Inquisitor's Arrival",
          "intent": "Introduce the ultimate System enforcer.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The Level 99 Inquisitor corners Kaelen in the city ruins."
        },
        {
          "section_id": 2,
          "title": "The Exploit Battle",
          "intent": "A tactical fight where Kaelen must use his glitches to survive.",
          "section_role": "conflict",
          "target_scene_count": 3,
          "end_condition": "Kaelen finds the 'Admin' vulnerability in the Inquisitor's code."
        },
        {
          "section_id": 3,
          "title": "Gaining Access",
          "intent": "Kaelen turns the tables on the System.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Kaelen absorbs the Inquisitor's administrative privileges."
        }
      ]
    },
    {
      "chapter_id": 11,
      "sections": [
        {
          "section_id": 1,
          "title": "The Final Ascent",
          "intent": "The final push toward the center of the world's code.",
          "section_role": "setup",
          "target_scene_count": 4,
          "end_condition": "Kaelen and Lyra reach the entrance to the Rift Core."
        },
        {
          "section_id": 2,
          "title": "The Core Guardians",
          "intent": "Defeat the last line of System defenses.",
          "section_role": "conflict",
          "target_scene_count": 4,
          "end_condition": "The last System defense mechanism is shattered."
        },
        {
          "section_id": 3,
          "title": "The Choice",
          "intent": "The ultimate decision on the fate of the world.",
          "section_role": "climax",
          "target_scene_count": 5,
          "end_condition": "Kaelen shatters the final System constraint, fully awakening the Void."
        }
      ]
    },
    {
      "chapter_id": 12,
      "sections": [
        {
          "section_id": 1,
          "title": "The New World Order",
          "intent": "Show the immediate consequences of the System's collapse.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Kaelen surveys the transformed, lawless landscape."
        },
        {
          "section_id": 2,
          "title": "Setting Up Base",
          "intent": "Establish a new status quo for the survivors.",
          "section_role": "investigation",
          "target_scene_count": 3,
          "end_condition": "The first 'Void-Base' is established in the ruins of the old world."
        },
        {
          "section_id": 3,
          "title": "The Next Quest",
          "intent": "Hook the reader for the next book in the series.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Kaelen accepts the new quest: 'Rebuild Reality'."
        }
      ]
    }
  ]
}

